Senda.Knowledge:Register({
  id = "general-gold",
  class = "ANY",
  kind = "page",
  title = "Oro sin recolectar",
  order = 230,
  status = "unverified",
  note = "Precios de la casa de subastas del 9-nov (reino del autor). Equitación gratis para el brujo: corrección de Blizzard del 9-nov citada sin enlace.",
  block = {
    { heading = "Cómo entra el oro sin recolectar", body = "- **Misiones:** el oro de las recompensas. Si no te sirve ninguna recompensa, elige la que más valga.\n- **Grises** al vendedor, siempre.\n- **Mazmorras:** azules y verdes ligados al equiparse, a la casa de subastas.\n- **Bolsas:** las de tejido mágico rojo y las de componentes se venden bien.\n- **Encantar a otros:** ofrece en Comercio que el cliente pone los materiales y tú cobras la mano de obra.\n- **Lo que sobre:** polvos, esencias y paño que no vayas a usar." },
    { heading = "Materiales", body = "- **Paño:** cae de humanoides, gratis.\n- **Hilo y tintes:** proveedor de suministros comerciales.\n- **Polvos y esencias:** desencanta.\n- **Patrones nuevos:** Favor de mercader (cajas de suministros en Tres Caminos; caen también en mazmorras).\n- **Lo que falte:** casa de subastas (unos 81 de oro todo el paño e hilo hasta Sastrería 225, precios del 9 nov)." },
    { heading = "Reglas de casa de subastas", body = "- Mira el precio antes de vender al vendedor.\n- No vendas lo fabricado al vendedor: Blizzard bajó mucho esos precios.\n- Si no se vende, pierdes el depósito: no pongas precios absurdos.\n- La primera semana todo está caro; los materiales de nivel bajo suelen bajar mucho en dos semanas." },
    { heading = "Gastos que vienen", body = "- Hechizos de clase en cada nivel par.\n- Rangos de profesión.\n- Equitación al 40: gratis para el brujo, viene con la misión del Corcel nefasto (corrección del 9 nov). El mago la paga (unos 100 de oro).\n- Los patrones con Favor no cuestan oro." },
  },
})

Senda.Knowledge:Register({
  id = "duo-intro",
  class = "ANY",
  kind = "page",
  title = "En pareja: brujo gnomo + mago humano",
  order = 300,
  status = "unverified",
  note = "Manual del Mago Gnomo (sección «En pareja»), contrastado el 10-nov con ConquestCapped, Warcraft Tavern, Method y las correcciones de Blizzard. Bonificación del 50% en mazmorras: Blizzard 8-nov, sin enlace.",
  block = {
    { heading = "Estar en la misma capa del servidor", body = "- Los dos tenéis que estar en el **mismo reglamento** (normal, JcJ…) y en la **misma facción**: si no, no podéis agruparos.\n- **Invita a tu compañero al grupo.** El juego le ofrece moverse a la copia del mundo del líder.\n- Abajo a la izquierda sale un aviso con un temporizador: pulsa **«Actualizar ahora» (Refresh Now)** para pasar al momento en lugar de esperar.\n- Si seguís sin veros, que el invitado salga y vuelva a entrar en la zona, o salid del grupo y volved a agruparos.\n- Las fases de misión son otra cosa: si uno tiene una misión más avanzada, puede ver el mundo distinto. Haced las cadenas a la vez.", status = "unverified" },
    { heading = "Cómo funciona la experiencia en grupo (Forever)", body = "- **Misiones:** los dos cobráis la experiencia entera. Algunos objetos de misión los recoge todo el grupo.\n- **Enemigos:** la experiencia se reparte entre los dos. Desde el 8 de noviembre los enemigos de mazmorra dan un 50% más.\n- **Mazmorras:** sus misiones dan unas 2,4 veces lo de Classic. Máximo 5 mazmorras por hora.\n- **Descanso:** solo duplica la experiencia de enemigos, no la de misiones." },
    { heading = "Reparto de papeles", body = "- El Abisario aguanta al primer enemigo. El brujo pone DoTs y el mago lanza Descarga de Escarcha.\n- Si aparece un segundo: el mago usa Polimorfia y el brujo Miedo, cada uno a un enemigo distinto.\n- Contra grupos: el Abisario los junta y el mago usa Nova de Escarcha y Deflagración Arcana. Nada de Miedo ahí.\n- El mago da agua conjurada e Intelecto Arcano. El brujo da Piedras de salud (macro SND_Piedra del mago) y Piedra de alma al mago en sitios peligrosos." },
    { heading = "Botín y profesiones", body = "- Los dos sois Sastrería + Encantamiento: compartid el trabajo. Uno hace las madejas y el otro desencanta, o turnaos el paño.\n- Botín «Libre para todos» entre los dos; en mazmorra, «Botín de grupo» con umbral en verde.\n- Lo de Sombras para el brujo y lo de Escarcha para el mago. Conjuntos de Sastrería: Sombras (brujo) y Silky (mago)." },
  },
})

Senda.Knowledge:Register({
  id = "duo-1-10",
  class = "ANY",
  kind = "page",
  title = "Niveles 1-10: cada uno en su zona",
  levels = {1, 10},
  order = 310,
  status = "unverified",
  block = {
    { heading = "Dónde", body = "El brujo gnomo empieza en Dun Morogh (Valle de Crestanevada, Kharanos) y el mago humano en Villanorte y el Bosque de Elwynn. No merece la pena juntarse antes del 10: las misiones de clase y de inicio son de cada raza." },
    { heading = "Punto de encuentro", body = "**Villadorada** (Bosque de Elwynn, 42, 65). El brujo llega a Ventormenta en el Tren subterráneo de Forjaz y sale por la puerta principal." },
    { heading = "Antes de juntaros", body = "- **Brujo:** misión del Abisario (nivel 10: sótano de El Cordero Degollado en Ventormenta y la Plantación de Brackwell en Elwynn). Entre los dos, Surena Caledon es fácil.\n- **Mago:** Habla con Jennea y el Lago Espejo (nivel 10, también en Elwynn y Ventormenta).\n- **Los dos:** Sastrería, Encantamiento y Primeros auxilios aprendidas. El paño de lino, a guardar." },
  },
})

Senda.Knowledge:Register({
  id = "duo-10-12",
  class = "ANY",
  kind = "page",
  title = "Niveles 10-12: Elwynn y Ventormenta",
  levels = {10, 12},
  order = 320,
  status = "unverified",
  block = {
    { heading = "Dónde", body = "Bosque de Elwynn y Ventormenta. Mientras uno hace su misión de clase, el otro le acompaña: así os igualáis de nivel.\n\n- **Abisario:** Gakin en el sótano de El Cordero Degollado (39.2, 85.2) y Surena Caledon en la Plantación de Brackwell (71.0, 80.6).\n- **Lago Espejo del mago:** cascada al suroeste de las puertas de Ventormenta (hacia 32, 58)." },
    { heading = "Profesiones", body = "Lino de Defias y kóbolds. Madejas de paño de lino. Entrenad **Oficial** (habilidad 50 y nivel 10): Sellandus o Georgio Bolero (Sastrería) y Lucan Cordell (Encantamiento), en el Barrio de los Magos de Ventormenta. Lawrence Schneider solo enseña Aprendiz." },
  },
})

Senda.Knowledge:Register({
  id = "duo-12-15",
  class = "ANY",
  kind = "page",
  title = "Niveles 12-15: Páramos de Poniente",
  levels = {12, 15},
  order = 330,
  status = "unverified",
  block = {
    { heading = "Dónde", body = "Base en la Colina del Centinela (56, 47) y la granja Saldean (56, 31). Misiones de Defias y gnolls Pellejorrío. Old Murk-Eye (élite) entre los dos (dato de Classic).\n\nAl 14, si os apetece, la cadena del Saco de dormir acogedor en la granja Alexston (37, 50): es larga y sale de la ruta.", note = "«(Classic)» en la fuente: dato del Classic original, sin comprobar en Forever." },
    { heading = "Profesiones", body = "El mejor sitio de lino: Defias de la mina Jangolode (43, 22) y gnolls junto a la Colina (dato de Classic). Objetivo: Sastrería 75-100.", note = "«(Classic)» en la fuente." },
    { heading = "Táctica", body = "Defias en grupos de 2-3: Abisario al primero, Polimorfia al segundo y Miedo al tercero si hace falta. El mago no debe lanzar la Nova si el Abisario tiene la amenaza: los DoTs rompen la congelación." },
  },
})

Senda.Knowledge:Register({
  id = "duo-14-18",
  class = "ANY",
  kind = "page",
  title = "Niveles 14-18: Hall of Thanes y Crestagrana",
  levels = {14, 18},
  order = 340,
  status = "unverified",
  block = {
    { heading = "Hall of Thanes (14-17)", body = "Mazmorra de 5 dentro de Forjaz: buscad 3 jugadores (tanque y sanador). Entrada por el pasillo con telarañas a la izquierda del salón de Magni.\n\nCoged antes sus 5 misiones (unos 13.300 de experiencia):\n- **Important Heirlooms** (Thom Filch).\n- **The Restless Dead** (Afadra Dunwall).\n- **An Ancient Grudge** (dentro).\n- **The Treaty of Understanding** (tablilla de la última sala).\n- **Old Ironforge Incursion** (Earthseer Farsen, cantera de Gol'Bolar, Dun Morogh 64.8, 58.5)." },
    { heading = "Montañas Crestagrana y Tres Caminos (15-18)", body = "Misiones de Villa del Lago (dato de Classic). En Tres Caminos (10.5, 72.7) entregad cajas de suministros a Marcy Baker y comprad patrones de Sastrería con el Favor a Mivin Shadowweave: Sombras para el brujo y Silky para el mago.", note = "«(Classic)» en la fuente para las misiones de Villa del Lago." },
    { heading = "Favor de mercader", body = "- 20 Madejas de paño de lino dan 10 de Favor; 40 de lino suelto, solo 5. Haced madejas antes de entregar.\n- 20 de Polvo extraño dan 5 de Favor.\n- La primera entrega da una etiqueta cuya misión da 50 de Favor." },
  },
})

Senda.Knowledge:Register({
  id = "duo-18-22",
  class = "ANY",
  kind = "page",
  title = "Niveles 18-22: Minas de la Muerte",
  levels = {18, 22},
  order = 350,
  status = "unverified",
  block = {
    { heading = "Dónde", body = "Minas de la Muerte (Páramos de Poniente, Arroyo de la Luna). Mazmorra de 5: los dos solos no la vais a limpiar. Coged antes las misiones: la cadena de La Hermandad Defias (Gryan Stoutmantle, Colina del Centinela), Pañuelos de seda roja (Explorador Riell) y Collecting Memories (Ventormenta) (dato de Classic).", note = "«(Classic)» en la fuente." },
    { heading = "Botín", body = "Vara para remover galletas (varita) y Bastón de piedra de ascuas. Casi todo son humanoides: lino y lana a montones." },
    { heading = "Profesiones", body = "Entrenad **Experto** a 125 y nivel 20 (para Encantamiento, Kitta Firewind en la Torre de Azora, Elwynn)." },
