    { id = "mage-gem", class = "MAGE", when = "Conoces Conjurar ágata de maná y no llevas gema", say = "No llevas gema de maná: créala (se usa en combate sin gastar turno)." },
    { id = "bags-low", class = "ANY", when = "Menos de 4 huecos libres", say = "Solo te quedan N huecos en las bolsas. Vende grises o fabrica bolsas." },
